package app.boardlens.companion;
import java.util.*;import java.util.concurrent.*;import org.junit.Test;import static org.junit.Assert.*;
public class LatestWorkQueueTest {
 @Test public void changesKeepOnlyNewestWaitingPosition()throws Exception{List<Integer> done=Collections.synchronizedList(new ArrayList<>());CountDownLatch start=new CountDownLatch(1),release=new CountDownLatch(1),finish=new CountDownLatch(1);try(LatestWorkQueue q=new LatestWorkQueue("test")){q.submit(()->{start.countDown();try{release.await();done.add(1);}catch(InterruptedException ignored){}});assertTrue(start.await(2,TimeUnit.SECONDS));for(int i=2;i<=100;i++){final int n=i;q.submit(()->{done.add(n);finish.countDown();});}release.countDown();assertTrue(finish.await(2,TimeUnit.SECONDS));assertEquals(Arrays.asList(1,100),done);}}
 @Test public void closeDropsPendingWork()throws Exception{CountDownLatch start=new CountDownLatch(1),end=new CountDownLatch(1);List<Integer> done=Collections.synchronizedList(new ArrayList<>());LatestWorkQueue q=new LatestWorkQueue("stop");q.submit(()->{start.countDown();try{Thread.sleep(10000);}catch(InterruptedException ignored){}finally{end.countDown();}});assertTrue(start.await(2,TimeUnit.SECONDS));q.submit(()->done.add(2));q.close();q.submit(()->done.add(3));assertTrue(end.await(2,TimeUnit.SECONDS));assertTrue(done.isEmpty());}
 @Test public void cleanupWaitsForRunningInferenceWithoutBlockingCaller()throws Exception{CountDownLatch start=new CountDownLatch(1),release=new CountDownLatch(1),cleaned=new CountDownLatch(1);List<Integer> done=Collections.synchronizedList(new ArrayList<>());LatestWorkQueue q=new LatestWorkQueue("cleanup");q.submit(()->{start.countDown();try{release.await();done.add(1);}catch(InterruptedException ignored){}});assertTrue(start.await(2,TimeUnit.SECONDS));q.submit(()->done.add(99));q.close(()->{done.add(2);cleaned.countDown();});assertEquals(1,cleaned.getCount());release.countDown();assertTrue(cleaned.await(2,TimeUnit.SECONDS));assertEquals(Arrays.asList(1,2),done);}
}
